            $slots[] = [
                'weekday' => $weekday,
                'time' => substr($time, 0, 5),
            ];
        }
    }

    if (empty($slots)) {
        $candidates = [
            ['week', 'time'],
            ['week1', 'time1'],
            ['week2', 'time2'],
            ['week3', 'time3'],
            ['week4', 'time4'],
            ['week5', 'time5'],
            ['week6', 'time6'],
        ];
        $seenWeekdays = [];
        foreach ($candidates as [$weekField, $timeField]) {
            $weekday = (int) ($studentClass->{$weekField} ?? 0);
            if ($weekday < 1 || $weekday > 7) {
                continue;
